/* From Uiverse.io by Nawsome - Tags: switch */
.__UIV_SCOPE__ .checker {
  display: block;
  font-size: 25px;
  height: 1em;
  width: 2.5em;
  box-sizing: content-box;
  padding: 0.15em;
  border-radius: 0.25em;
  cursor: pointer;
}

.__UIV_SCOPE__ .checkmark {
  width: 1em;
  height: 1em;
  transform: translateX(-0.4em);
  z-index: 5;
}

.__UIV_SCOPE__ .checkmark svg {
  display: block;
  background: #e5e5e5;
  transform: translateX(0.4em);
  border-radius: 0.15em;
  transition: background-color var(--duration) ease, transform calc(var(--duration) * 1.5) ease;
}

.__UIV_SCOPE__ .checkmark svg path {
  stroke-dasharray: 90 90;
  stroke-dashoffset: 90;
  transition: stroke-dashoffset calc(var(--duration) / 3) linear calc(var(--duration) / 3);
}

.__UIV_SCOPE__ .checkbox {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0.4;
  visibility: hidden;
}

.__UIV_SCOPE__ .checkbox:checked ~ .checkmark {
  transform: translate(1.9em);
}

.__UIV_SCOPE__ .checkbox:checked ~ .checkmark svg {
  background: #77c44c;
  transform: translate(-0.4em);
}

.__UIV_SCOPE__ .checkbox:checked ~ .checkmark svg path {
  stroke-dashoffset: 0;
}

.__UIV_SCOPE__ .check-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: white;
  z-index: 2;
}

.__UIV_SCOPE__ .check-bg:before, .__UIV_SCOPE__ .check-bg:after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  border-radius: inherit;
}

.__UIV_SCOPE__ .check-bg:after {
  background: white;
}

.__UIV_SCOPE__ .check-bg:before {
  transform: translateY(30%);
  transform-origin: bottom center;
  background: black;
  filter: blur(0.25em);
  opacity: 0.2;
  z-index: -1;
}

.__UIV_SCOPE__ .checker.checker:active {
  transform: scale(0.85);
  transition-duration: calc(var(--duration) / 2);
}

.__UIV_SCOPE__ .checker.checker:active .check-bg::before {
  transform: translateY(0) scale(0.8);
  opacity: 0.2;
}

.__UIV_SCOPE__ *,
.__UIV_SCOPE__ *::before,
.__UIV_SCOPE__ *::after {
  box-sizing: border-box;
  position: relative;
}

.__UIV_SCOPE__ {
  height: 100%;
}

.__UIV_SCOPE__ {
  background-color: #f2f2f2;
  height: 100%;
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}
